<script setup lang="ts">import {ref} from "vue";import {ElMessage,ElMessageBox} from "element-plus";import {closePeriod} from "../../api/cost";const period=ref("");async function close(){try{await ElMessageBox.confirm("确认结账？","确认");await closePeriod(period.value);ElMessage.success("结账成功")}catch{ElMessage.error("结账失败")}}</script><template><el-card><el-input v-model="period" placeholder="YYYY-MM"/><el-button @click="close">结账</el-button></el-card></template>
